<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/media_helpers.php'; require_once 'includes/make_mailer.php'; require 'includes/otp_helpers.php'; require_once 'includes/audit_log.php'; require 'includes/toasts.php'; require_once 'includes/psgc_helpers.php'; require_admin($pdo);
$messages=[];
$branches=$pdo->query("SELECT branch_id,name,status FROM branches WHERE status<>'archived' ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_check($_POST['csrf']??null)) $messages[]=['kind'=>'danger','text'=>'Session expired. Refresh and try again.'];
    elseif (!verify_account_password($pdo,(int)$_SESSION['user_id'],(string)($_POST['auth_password']??''))) $messages[]=['kind'=>'danger','text'=>'Your current admin password did not match.'];
    else {
        $id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);
        if (!$id || $id===(int)$_SESSION['user_id']) $messages[]=['kind'=>'danger','text'=>'You cannot change your own employee record here.'];
        elseif (($_POST['action']??'')==='edit_employee') {
            $first=trim((string)($_POST['first_name']??'')); $middle=trim((string)($_POST['middle_name']??'')); $last=trim((string)($_POST['last_name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $mobile=normalize_mobile(trim((string)($_POST['phone']??''))); $street=trim((string)($_POST['street_address']??'')); $regionCode=trim((string)($_POST['region_code']??'')); $municipalityCode=trim((string)($_POST['municipality_code']??'')); $barangayCode=trim((string)($_POST['barangay_code']??'')); $zip=trim((string)($_POST['zip_code']??'')); $place=psgc_resolve($pdo,$regionCode,$municipalityCode,$barangayCode); $role=(string)($_POST['role']??'');
            if (!preg_match(NAME_RE,$first)||!preg_match(NAME_RE,$last)||($middle!==''&&!preg_match(NAME_RE,$middle))) $messages[]=['kind'=>'danger','text'=>'Enter valid employee names.'];
            if (!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>255||!preg_match(MOBILE_RE,$mobile)||!$place||$street===''||mb_strlen($street)>255||!preg_match('/^\d{4}$/',$zip)||!preg_match('/^[a-z][a-z0-9_]{1,31}$/',$role)||in_array($role,['customer'],true)) $messages[]=['kind'=>'danger','text'=>'Review the employee email, contact number, address, and role.'];
            if (!$messages) { $dup=$pdo->prepare('SELECT 1 FROM user_credentials WHERE email=? AND user_id<>? UNION SELECT 1 FROM user_info WHERE phone=? AND user_id<>?'); $dup->execute([$email,$id,$mobile,$id]); if ($dup->fetchColumn()) $messages[]=['kind'=>'danger','text'=>'That email or contact number is already assigned.']; }
            $photoPath=null; if (!$messages && isset($_FILES['photo']) && ($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) { try { $photoPath=save_square_employee_photo($_FILES['photo']); } catch (Throwable $e) { $messages[]=['kind'=>'danger','text'=>$e->getMessage()]; } }
            if (!$messages) { $target=$pdo->prepare('SELECT c.role,c.email,i.first_name,i.middle_name,i.last_name,i.phone FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id WHERE c.user_id=?'); $target->execute([$id]); $oldEmployee=$target->fetch(PDO::FETCH_ASSOC); $oldRole=$oldEmployee['role']??null; if (!$oldRole||$oldRole==='customer') $messages[]=['kind'=>'danger','text'=>'Employee not found.']; elseif ($oldRole==='admin'&&$role!=='admin'&&(int)$pdo->query("SELECT COUNT(*) FROM user_credentials WHERE role='admin' AND is_active=1")->fetchColumn()<=1) $messages[]=['kind'=>'danger','text'=>'The last active admin cannot be changed to another role.']; }
            $branchIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['branch_ids']??[])),static fn($value)=>$value>0))); $oldBranchIds=[]; if(!$messages){$oldBranchQuery=$pdo->prepare('SELECT branch_id FROM branch_staff WHERE user_id=? ORDER BY branch_id');$oldBranchQuery->execute([$id]);$oldBranchIds=array_map('intval',$oldBranchQuery->fetchAll(PDO::FETCH_COLUMN));}
            if (!$messages && $role==='staff' && $branchIds) { $valid=$pdo->prepare("SELECT COUNT(*) FROM branches WHERE branch_id IN (".implode(',',array_fill(0,count($branchIds),'?')).") AND status<>'archived'"); $valid->execute($branchIds); if ((int)$valid->fetchColumn()!==count($branchIds)) $messages[]=['kind'=>'danger','text'=>'Choose only active branches for this staff member.']; }
            if (!$messages) { $pdo->beginTransaction(); try { if ($photoPath) $pdo->prepare('UPDATE user_info SET first_name=?,middle_name=?,last_name=?,phone=?,photo_path=? WHERE user_id=?')->execute([$first,$middle?:null,$last,$mobile,$photoPath,$id]); else $pdo->prepare('UPDATE user_info SET first_name=?,middle_name=?,last_name=?,phone=? WHERE user_id=?')->execute([$first,$middle?:null,$last,$mobile,$id]); $pdo->prepare('UPDATE user_credentials SET email=?,role=? WHERE user_id=?')->execute([$email,$role,$id]); $defaultAddress=$pdo->prepare('SELECT address_id FROM user_addresses WHERE user_id=? AND is_default=1 LIMIT 1'); $defaultAddress->execute([$id]); $addressId=(int)$defaultAddress->fetchColumn(); $recipient=trim(implode(' ',array_filter([$first,$middle,$last],'strlen'))); if($addressId){$pdo->prepare('UPDATE user_addresses SET recipient_name=?,recipient_phone=?,street_address=?,barangay_code=?,zip_code=? WHERE user_id=? AND address_id=?')->execute([$recipient,$mobile,$street,$place['barangay_code'],$zip,$id,$addressId]);}else{$pdo->prepare('INSERT INTO user_addresses(user_id,recipient_name,recipient_phone,street_address,barangay_code,zip_code,is_default) VALUES(?,?,?,?,?,?,1)')->execute([$id,$recipient,$mobile,$street,$place['barangay_code'],$zip]);} $pdo->prepare('DELETE FROM branch_staff WHERE user_id=?')->execute([$id]); if ($role==='staff') { $assign=$pdo->prepare('INSERT INTO branch_staff(branch_id,user_id) VALUES(?,?)'); foreach($branchIds as $branchId) $assign->execute([$branchId,$id]); } write_audit_log($pdo,'employee_details_updated','employee',(int)$id,['first_name'=>$oldEmployee['first_name'],'middle_name'=>$oldEmployee['middle_name'],'last_name'=>$oldEmployee['last_name'],'email'=>$oldEmployee['email'],'role'=>$oldRole,'phone'=>$oldEmployee['phone'],'branch_ids'=>$oldBranchIds],['first_name'=>$first,'middle_name'=>$middle?:null,'last_name'=>$last,'email'=>$email,'role'=>$role,'phone'=>$mobile,'branch_ids'=>$role==='staff'?$branchIds:[]]); $pdo->commit(); $_SESSION['flash_success']='Employee details and branch assignments saved successfully.'; header('Location: employees.php'); exit; } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Could not save employee details.']; } }
        } elseif (($_POST['action']??'')==='toggle_status') {
            $new=(int)($_POST['new_status']??-1); $target=$pdo->prepare("SELECT role,is_active FROM user_credentials WHERE user_id=? AND role<>'customer'"); $target->execute([$id]); $row=$target->fetch();
            if (!$row||!in_array($new,[0,1],true)) $messages[]=['kind'=>'danger','text'=>'Employee status could not be changed.'];
            elseif ((int)$row['is_active']===$new) $messages[]=['kind'=>'info','text'=>'Employee status is already up to date.'];
            elseif ($row['role']==='admin'&&$new===0&&(int)$pdo->query("SELECT COUNT(*) FROM user_credentials WHERE role='admin' AND is_active=1")->fetchColumn()<=1) $messages[]=['kind'=>'danger','text'=>'The last active admin cannot be deactivated.'];
            else { $pdo->beginTransaction(); try { $pdo->prepare('UPDATE user_credentials SET is_active=?,first_login_activation=0 WHERE user_id=?')->execute([$new,$id]); write_audit_log($pdo,'employee_status_changed','employee',(int)$id,['is_active'=>(int)$row['is_active'],'role'=>$row['role']],['is_active'=>$new,'role'=>$row['role']]); $pdo->commit(); $_SESSION['flash_success']=$new?'Employee account activated.':'Employee account deactivated.'; header('Location: employees.php'); exit; } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Employee status could not be changed.']; } }
        } elseif (($_POST['action']??'')==='reset_staff_password') {
            $target=$pdo->prepare("SELECT c.email,c.role,i.first_name,i.middle_name,i.last_name FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id WHERE c.user_id=?"); $target->execute([$id]); $employee=$target->fetch();
            if (!$employee||$employee['role']!=='staff') $messages[]=['kind'=>'danger','text'=>'Password reset is available for staff accounts only.'];
            else {
                $temporaryPassword='$Nomcha'.random_int(100000,999999); $fullName=trim(implode(' ',array_filter([$employee['first_name'],$employee['middle_name'],$employee['last_name']])));
                try { $pdo->beginTransaction(); $pdo->prepare('UPDATE user_credentials SET password_hash=? WHERE user_id=?')->execute([password_hash($temporaryPassword,PASSWORD_DEFAULT),$id]); $pdo->prepare("UPDATE auth_otp_challenges SET consumed_at=NOW() WHERE user_id=? AND purpose='password_reset' AND consumed_at IS NULL")->execute([$id]); send_employee_welcome_email((string)$employee['email'],$fullName,$temporaryPassword); auth_security_log($pdo,'admin_password_reset',(int)$_SESSION['user_id'],'password_reset','completed',['target_user_id'=>(int)$id]); write_audit_log($pdo,'employee_password_reset','employee',(int)$id,null,['notification_sent'=>true]); $pdo->commit(); $_SESSION['flash_success']='Staff password reset. A temporary password was emailed.'; header('Location: employees.php'); exit; }
                catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $messages[]=['kind'=>'danger','text'=>'Password could not be reset or emailed. Check Make setup and try again.']; }
            }
        }
    }
}
$employees=$pdo->prepare("SELECT c.user_id,c.role,c.email,c.is_active,i.first_name,i.middle_name,i.last_name,i.phone,i.photo_path,a.address_id,a.street_address,r.psgc_code AS region_code,l.psgc_code AS municipality_code,l.name AS municipality,b.psgc_code AS barangay_code,b.name AS barangay,r.name AS region,a.zip_code FROM user_credentials c JOIN user_info i ON i.user_id=c.user_id LEFT JOIN user_addresses a ON a.user_id=c.user_id AND a.is_default=1 LEFT JOIN psgc_barangays b ON b.psgc_code=a.barangay_code LEFT JOIN psgc_localities l ON l.psgc_code=b.locality_code LEFT JOIN psgc_provinces p ON p.psgc_code=l.province_code LEFT JOIN psgc_regions r ON r.psgc_code=COALESCE(l.region_code,p.region_code) WHERE c.role<>'customer' AND c.user_id<>? ORDER BY i.last_name,i.first_name"); $employees->execute([(int)$_SESSION['user_id']]); $employees=$employees->fetchAll();
foreach ($employees as &$employee) {
    $employee['display_address'] = trim(implode(', ', array_filter([
        $employee['street_address'] ?? '', $employee['barangay'] ?? '', $employee['municipality'] ?? '', $employee['region'] ?? '', $employee['zip_code'] ?? '',
    ], static fn($part): bool => trim((string)$part) !== '')));
}
unset($employee);
$employeePsgc=psgc_form_state($pdo,[]);
$employeeBranches=[]; foreach($pdo->query('SELECT user_id,branch_id FROM branch_staff')->fetchAll(PDO::FETCH_ASSOC) as $assignment) $employeeBranches[(int)$assignment['user_id']][]=(int)$assignment['branch_id']; foreach($employees as &$employee) $employee['branch_ids']=$employeeBranches[(int)$employee['user_id']]??[]; unset($employee);
$success=$_SESSION['flash_success']??null; unset($_SESSION['flash_success']); if ($success) array_unshift($messages,['kind'=>'success','text'=>$success]);
$pageTitle='Employee management'; require 'includes/header.php'; render_toasts($messages);
?>
