<script>
document.addEventListener('DOMContentLoaded',()=>{let chosen=null;const details=new bootstrap.Modal('#employeeDetailsModal'),edit=new bootstrap.Modal('#editEmployeeModal'),editConfirm=new bootstrap.Modal('#editEmployeeConfirm'),statusConfirm=new bootstrap.Modal('#employeeStatusConfirm'),resetPasswordConfirm=new bootstrap.Modal('#resetStaffPasswordConfirm');
const cards=[...document.querySelectorAll('[data-employee]')],search=document.getElementById('employee-search'),roleFilter=document.getElementById('role-filter'),sortKey=document.getElementById('sort-key'),sortDir=document.getElementById('sort-dir'),empty=document.getElementById('employee-empty');
function updateBranchField(){document.getElementById('employee-branch-assignment').hidden=document.getElementById('edit-role').value!=='staff';}
function syncBranchToggles(ids){const buttons=[...document.querySelectorAll('[data-branch-toggle]')],available=new Set(buttons.map(button=>Number(button.dataset.branchToggle))),selected=new Set(ids.map(Number).filter(id=>available.has(id)));buttons.forEach(button=>{const isAssigned=selected.has(Number(button.dataset.branchToggle));button.textContent=isAssigned?'Assigned':'Unassigned';button.setAttribute('aria-pressed',isAssigned?'true':'false');button.classList.toggle('btn-outline-secondary',!isAssigned);button.classList.toggle('btn-success',isAssigned);});const inputs=document.getElementById('employee-branch-inputs');inputs.replaceChildren(...[...selected].map(id=>{const input=document.createElement('input');input.type='hidden';input.name='branch_ids[]';input.value=String(id);return input;}));}
async function setEdit(){document.getElementById('edit-user-id').value=chosen.user_id;document.getElementById('edit-first').value=chosen.first_name||'';document.getElementById('edit-middle').value=chosen.middle_name||'';document.getElementById('edit-last').value=chosen.last_name||'';document.getElementById('edit-email').value=chosen.email||'';document.getElementById('edit-phone').value=chosen.phone||'';document.getElementById('edit-phone').dispatchEvent(new Event('input',{bubbles:true}));document.getElementById('edit-street-address').value=chosen.street_address||'';document.getElementById('edit-zip-code').value=chosen.zip_code||'';await window.PsgcSelect.setSelection(document.getElementById('employeeEditForm'),chosen);document.getElementById('edit-role').value=chosen.role;syncBranchToggles(chosen.branch_ids||[]);updateBranchField();const p=document.getElementById('employee-photo-preview');p.src=chosen.photo_path||'assets/employee-placeholder.svg';p.hidden=false;}
cards.forEach(card=>card.addEventListener('click',()=>{chosen=JSON.parse(card.dataset.employee);const name=[chosen.first_name,chosen.middle_name,chosen.last_name].filter(Boolean).join(' ');document.getElementById('detail-photo').src=chosen.photo_path||'assets/employee-placeholder.svg';document.getElementById('detail-name').textContent=name;document.getElementById('detail-role').textContent=chosen.role;document.getElementById('detail-email').textContent=chosen.email||'—';document.getElementById('detail-phone').textContent=chosen.phone||'—';document.getElementById('detail-address').textContent=chosen.display_address||'—';document.getElementById('detail-status').textContent=Number(chosen.is_active)?'Active':'Deactivated';document.getElementById('toggleEmployeeButton').textContent=Number(chosen.is_active)?'Deactivate':'Activate';document.getElementById('toggleEmployeeButton').className='btn '+(Number(chosen.is_active)?'btn-danger':'btn-success');document.getElementById('resetEmployeePasswordButton').hidden=chosen.role!=='staff';details.show();}));
document.querySelectorAll('[data-branch-toggle]').forEach(button=>button.addEventListener('click',()=>{const selected=[...document.querySelectorAll('[data-branch-toggle][aria-pressed="true"]')].map(item=>Number(item.dataset.branchToggle));const id=Number(button.dataset.branchToggle);syncBranchToggles(selected.includes(id)?selected.filter(item=>item!==id):[...selected,id]);}));document.getElementById('edit-role').addEventListener('change',updateBranchField);document.getElementById('editEmployeeButton').addEventListener('click',async()=>{await setEdit();document.getElementById('employeeDetailsModal').addEventListener('hidden.bs.modal',()=>edit.show(),{once:true});details.hide();});document.getElementById('openEditConfirm').addEventListener('click',()=>{const form=document.getElementById('employeeEditForm'),password=document.getElementById('edit-auth-password');password.required=false;const valid=form.reportValidity();password.required=true;if(valid){document.getElementById('editEmployeeModal').addEventListener('hidden.bs.modal',()=>editConfirm.show(),{once:true});edit.hide();}});
document.getElementById('toggleEmployeeButton').addEventListener('click',()=>{document.getElementById('status-user-id').value=chosen.user_id;document.getElementById('status-new-value').value=Number(chosen.is_active)?0:1;document.getElementById('status-copy').textContent=(Number(chosen.is_active)?'Deactivate':'Activate')+' '+[chosen.first_name,chosen.last_name].filter(Boolean).join(' ')+'?';document.getElementById('confirm-status-button').textContent=Number(chosen.is_active)?'Deactivate employee':'Activate employee';details.hide();statusConfirm.show();});
document.getElementById('resetEmployeePasswordButton').addEventListener('click',()=>{document.getElementById('reset-staff-user-id').value=chosen.user_id;document.getElementById('reset-staff-name').textContent=[chosen.first_name,chosen.middle_name,chosen.last_name].filter(Boolean).join(' ');details.hide();resetPasswordConfirm.show();});
function refresh(){const q=search.value.trim().toLowerCase();const visible=cards.filter(c=>{const wrap=c.closest('.employee-card-wrap');const show=wrap.dataset.name.includes(q)&&(!roleFilter.value||wrap.dataset.role===roleFilter.value);wrap.hidden=!show;return show;});visible.sort((a,b)=>{const aw=a.closest('.employee-card-wrap'),bw=b.closest('.employee-card-wrap');const av=sortKey.value==='role'?aw.dataset.role:aw.dataset.name,bv=sortKey.value==='role'?bw.dataset.role:bw.dataset.name;return av.localeCompare(bv)*(sortDir.value==='asc'?1:-1);});const grid=document.getElementById('employee-grid');visible.forEach(c=>grid.appendChild(c.closest('.employee-card-wrap')));empty.hidden=visible.length>0;}[search,roleFilter,sortKey,sortDir].forEach(control=>{control.addEventListener('input',refresh);control.addEventListener('change',refresh);});refresh();
});
</script>
